<Variable name="twitter" description="Twitter or X handle without the at sign blank none" type="string" default="" value=""/>
<Variable name="authorSameAs" description="Author profile links for SEO comma separated GitHub LinkedIn X" type="string" default="" value=""/>
<Variable name="locale" description="Open Graph locale like en US" type="string" default="en_US" value="en_US"/>
<Variable name="googleVerify" description="Google Search Console verification code" type="string" default="" value=""/>
