      if (!name || !/^(https?:\/\/|\/|#|mailto:)/i.test(url)) return;
      var li = el('li'), a = el('a', '', name); a.href = url; li.appendChild(a); ul.appendChild(li);
    });
  });

  /* ---------- Social icons (name -> svg path, static trusted markup) ---------- */
  var ICONS = {
